  bool _economy_apply(String user, int delta, String? key) {
    if (key != null) {
      final dupRows = economy_db.select('SELECT 1 FROM ledger WHERE key = ?', [key]);
      final bool dup = dupRows.isNotEmpty;
      if (dup) {
        return true;
      }
    }
    economy_db.execute('BEGIN IMMEDIATE');
    try {
      final curRows = economy_db.select('SELECT balance FROM balances WHERE user = ?', [user]);
      final int cur = curRows.isEmpty ? 0 : int.parse(curRows.first['balance'] as String);
      final next = NewrRt.add(cur, delta);
