  bool economy_transfer(String from, String to, int amount, String? key) {
    if (key != null) {
      final dupRows = economy_db.select('SELECT 1 FROM ledger WHERE key = ?', [key]);
      final bool dup = dupRows.isNotEmpty;
      if (dup) {
