    }
    economy_db.execute('BEGIN IMMEDIATE');
    try {
      final curFromRows = economy_db.select('SELECT balance FROM balances WHERE user = ?', [from]);
      final int curFrom = curFromRows.isEmpty ? 0 : int.parse(curFromRows.first['balance'] as String);
      final fromBalance = curFrom;
      if (fromBalance < amount) {
        economy_db.execute('ROLLBACK');
        return false;
      }
      final nextFrom = NewrRt.sub(fromBalance, amount);
      economy_db.execute('INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance', [from, nextFrom.toString()]);
      if (key != null) {
        economy_db.execute('INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)', [from, NewrRt.sub(0, amount).toString(), key, DateTime.now().millisecondsSinceEpoch ~/ 1000]);
      }
      // Heal the receiver's ledger: a previous failed transfer may have logged the out leg but not the in leg; replay it with the opposite key before crediting.
      var healed = false;
      var sumOut = 0;
      var sumIn = 0;
      var sumKeys = 0;
      final ledgerRows = economy_db.select('SELECT amount, key FROM ledger WHERE user = ?', [to]);
      for (final row in ledgerRows) {
        final k = row['key'] as String?;
        final a = int.parse(row['amount'] as String);
        if (k != null && k.endsWith(':out')) {
          sumOut = NewrRt.add(sumOut, a);
        } else if (k != null && k.endsWith(':in')) {
          sumIn = NewrRt.add(sumIn, a);
        } else {
          sumKeys = NewrRt.add(sumKeys, a);
        }
      }
      if (sumOut > 0 && sumIn == 0) {
        final heal = amount < sumOut ? amount : sumOut;
        economy_db.execute('INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)', [to, heal.toString(), key != null ? key + ':in' : null, DateTime.now().millisecondsSinceEpoch ~/ 1000]);
        healed = true;
      }
      final curToRows = economy_db.select('SELECT balance FROM balances WHERE user = ?', [to]);
      final int curTo = curToRows.isEmpty ? 0 : int.parse(curToRows.first['balance'] as String);
      final toBalance = curTo;
      final nextTo = NewrRt.add(toBalance, amount);
      if (!healed) {
        economy_db.execute('INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)', [to, amount.toString(), key != null ? key + ':in' : null, DateTime.now().millisecondsSinceEpoch ~/ 1000]);
      }
      economy_db.execute('INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance', [to, nextTo.toString()]);
      economy_db.execute('COMMIT');
      return true;
    } catch (e) {
      _economy_rollback();
      rethrow;
    }
  }

