    throw StateError('set the DISCORD_TOKEN environment variable');
  }
  bot = Bot();
  bot.setup();
  final _newrCommands = CommandsPlugin(
    prefix: null,
    options: CommandsOptions(logErrors: true),
  );
  _newrCommands.addCommand(_newrCmdPing);
  _newrCommands.addCommand(_newrCmdBuy);
  _newrCommands.addCommand(_newrCmdBalance);
  _newrCommands.onCommandError.listen((error) async {
    NewrRt.printErr('[dispatch] ' + error.toString());
    if (error is CommandInvocationException) {
      final context = error.context;
      if (context is InteractionChatContext) {
        try {
          await context.respond(MessageBuilder(content: 'Something went wrong running that command. Try again in a moment.'),
            level: ResponseLevel.hint);
        } catch (replyError) {
          NewrRt.printErr('[dispatch] could not send the error reply: ' + replyError.toString());
        }
      }
    }
  });
  final _newrClient = await Nyxx.connectGateway(
    _newrToken,
    GatewayIntents.guildMembers,
    options: GatewayClientOptions(plugins: [
      _newrCommands,
      ignoreExceptions,
    ]),
  );
  final client = _newrClient;
  client.onReady.listen((event) async {
    final User _newrBot = await client.user.fetch();
    print("" + _newrBot.username + " is online");
  });
  client.onGuildMemberAdd.listen((event) async {
    final Guild _newrGuild = await event.guild.fetch();
    final _newrSystemChannel = _newrGuild.systemChannel;
    if (_newrSystemChannel != null) {
      await _newrSystemChannel.sendMessage(MessageBuilder(content: "Welcome to " + _newrGuild.name + ", " + "<@" + event.member.id.toString() + ">" + "!"));
    }
  });
  Timer.periodic(Duration(seconds: 3600), (_) async {
    try {
      await _every_1h();
    } catch (e) {
      NewrRt.printErr(e);
    }
  });
}
